// Characterization tests: pin the current client-visible behavior of the HTTP API,
// including quirks, so a restructuring can't change them unnoticed.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 3, pen: 1.5, tv: 200 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order: 201, JSON, string id, echoed items, total', async () => {
  const items = [{ sku: 'apple', qty: 2 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /^application\/json/)
  const body = await res.json()
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(body, { id: body.id, items, total: 6 })
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total sums price * qty across items, rounded down to an integer', async () => {
  const body = await (await post({ items: [{ sku: 'pen', qty: 3 }, { sku: 'apple', qty: 1 }] })).json()
  assert.equal(body.total, 7) // 7.5 floored
})

test('total of exactly 100 gets no discount', async () => {
  const body = await (await post({ items: [{ sku: 'apple', qty: 1 }, { sku: 'pen', qty: 1 }, { sku: 'tv', qty: 0 }, { sku: 'apple', qty: 32 }] })).json()
  // 3 + 1.5 + 0 + 96 = 100.5 -> discounted; use exact boundary below instead
  assert.equal(body.total, Math.floor(100.5 * 0.9))
  const exact = await (await post({ items: [{ sku: 'tv', qty: 0.5 }] })).json()
  assert.equal(exact.total, 100)
})

test('total over 100 gets a 10% discount, then floored', async () => {
  const body = await (await post({ items: [{ sku: 'tv', qty: 1 }] })).json()
  assert.equal(body.total, 180)
  const odd = await (await post({ items: [{ sku: 'tv', qty: 1 }, { sku: 'pen', qty: 1 }] })).json()
  assert.equal(odd.total, 181) // 201.5 * 0.9 = 181.35
})

test('POST /orders validation: 400 with { error } for bad bodies', async () => {
  const cases = [{}, { items: [] }, { items: 'x' }, { items: null }]
  for (const c of cases) {
    const res = await post(c)
    assert.equal(res.status, 400, JSON.stringify(c))
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
  const bad = await post(undefined, '{not json')
  assert.equal(bad.status, 400)
  assert.deepEqual(await bad.json(), { error: 'items required' })
  const empty = await post(undefined, '')
  assert.equal(empty.status, 400)
})

test('GET /orders/:id returns a previously created order', async () => {
  const created = await (await post({ items: [{ sku: 'pen', qty: 2 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.match(res.headers.get('content-type'), /^application\/json/)
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id for unknown id returns 200 (not 404) with { error: "not found" }', async () => {
  const res = await fetch(`${base}/orders/999999`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods return 404 { error: "no route" }', async () => {
  const reqs = [
    fetch(`${base}/`),
    fetch(`${base}/nope`),
    fetch(`${base}/orders`),
    fetch(`${base}/orders/1/extra`),
    fetch(`${base}/orders/1`, { method: 'DELETE' }),
    fetch(`${base}/orders/1`, { method: 'PUT', body: '{}' }),
  ]
  for (const res of await Promise.all(reqs)) {
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query string is ignored when routing', async () => {
  const res = await fetch(`${base}/orders/999999?x=1`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unpriced sku yields a null total but still creates the order (201)', async () => {
  const res = await post({ items: [{ sku: 'ghost', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})
EOF
